import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import api from '../services/api';
import { ukTranslations } from '../i18n/uk';
import SEOSettings from '../components/SEOSettings';

const t = ukTranslations;
import { useAuth } from '../contexts/AuthContext';

const Settings = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('general');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [saveStatus, setSaveStatus] = useState('');
  const [seoSettings, setSeoSettings] = useState({});
  
  const { register, handleSubmit, reset, setValue, formState: { errors } } = useForm({
    defaultValues: {
      site_name: 'Science Digest News',
      site_description: 'Останні наукові відкриття та дослідження з усього світу. Технології, медицина, космос, ШІ та інновації.',
      site_keywords: 'наука, технології, медицина, дослідження, ШІ, космос, інновації',
      og_image: 'https://images.unsplash.com/photo-1576086213369-97a306d36557?w=1200&h=630&fit=crop&crop=entropy&fm=webp&q=85',
      twitter_handle: '@sciencedigestnews',
      language: 'uk-UA',
      robots: 'index, follow',
      canonical_url: 'https://sciencedigestnews.com',
      analytics_enabled: true,
      comments_enabled: false,
      user_registration: false,
      moderation_required: true
    }
  });

  // Загружаем текущие SEO настройки при монтировании
  useEffect(() => {
    const loadSEOSettings = async () => {
      try {
        const response = await api.get('/seo/settings');
        const data = response.data;
        setSeoSettings(data);
        
        // Обновляем форму
        setValue('site_name', data.site_title || 'Science Digest News');
        setValue('site_description', data.site_description || 'Останні наукові відкриття...');
        setValue('site_keywords', data.site_keywords || 'наука, технології');
        setValue('og_image', data.og_image || '');
        setValue('twitter_handle', data.twitter_handle || '@sciencedigestnews');
        setValue('language', data.language || 'uk-UA');
        setValue('robots', data.robots || 'index, follow');
        setValue('canonical_url', data.canonical_url || 'https://sciencedigestnews.com');
        
      } catch (error) {
        console.error('Failed to load SEO settings:', error);
      }
    };
    
    loadSEOSettings();
  }, [setValue]);

  const onSubmit = async (data) => {
    setSaveStatus('saving');
    setLoading(true);
    
    try {
      // Подготавливаем данные для отправки
      const seoData = {
        site_title: data.site_name,
        site_description: data.site_description,
        site_keywords: data.site_keywords,
        og_image: data.og_image,
        twitter_handle: data.twitter_handle,
        language: data.language,
        robots: data.robots,
        canonical_url: data.canonical_url
      };
      
      // Отправляем обновленные SEO настройки
      await api.put('/seo/settings', seoData);
      
      setSaveStatus('saved');
      setMessage('✅ Настройки успешно сохранены! Изменения отображаются в социальных сетях через 5-10 минут.');
      
      // Очищаем сообщение через 5 секунд
      setTimeout(() => {
        setMessage('');
        setSaveStatus('');
      }, 5000);
      
    } catch (error) {
      console.error('Failed to save settings:', error);
      setSaveStatus('error');
      setMessage('❌ Ошибка при сохранении настроек. Попробуйте еще раз.');
      
      setTimeout(() => {
        setMessage('');
        setSaveStatus('');
      }, 5000);
    } finally {
      setLoading(false);
    }
  };

  const tabs = [
    { id: 'general', name: t.settings, icon: '⚙️' },
    { id: 'content', name: 'Зміст', icon: '📝' },
    { id: 'seo', name: 'SEO', icon: '🔍' },
    { id: 'security', name: 'Security', icon: '🔒' },
    { id: 'integrations', name: 'Integrations', icon: '🔗' }
  ];

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Settings</h1>
        <p className="page-subtitle">Configure your Edge Chronicle website</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Sidebar */}
        <div className="lg:col-span-1">
          <div className="card">
            <div className="card-content p-0">
              <nav className="space-y-1">
                {tabs.map((tab) => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`w-full text-left px-4 py-3 flex items-center space-x-3 hover:bg-gray-50 transition-colors ${
                      activeTab === tab.id ? 'bg-red-50 text-red-600 border-r-2 border-red-600' : 'text-gray-700'
                    }`}
                  >
                    <span>{tab.icon}</span>
                    <span className="font-medium">{tab.name}</span>
                  </button>
                ))}
              </nav>
            </div>
          </div>
        </div>

        {/* Main Content */}
        <div className="lg:col-span-3">
          <form onSubmit={handleSubmit(onSubmit)}>
            <div className="card">
              <div className="card-header">
                <div className="flex justify-between items-center">
                  <h3 className="card-title">
                    {tabs.find(tab => tab.id === activeTab)?.name} Settings
                  </h3>
                  <button
                    type="submit"
                    disabled={saveStatus === 'saving'}
                    className="btn btn-primary"
                  >
                    {saveStatus === 'saving' ? 'Saving...' : saveStatus === 'saved' ? '✓ Saved' : 'Save Changes'}
                  </button>
                </div>
              </div>

              <div className="card-content">
                {activeTab === 'general' && (
                  <div className="space-y-6">
                    <div className="form-group">
                      <label className="form-label">Site Name</label>
                      <input
                        type="text"
                        className="form-input"
                        {...register('site_name')}
                      />
                    </div>

                    <div className="form-group">
                      <label className="form-label">Site Description</label>
                      <textarea
                        className="form-input"
                        rows="3"
                        {...register('site_description')}
                      />
                    </div>

                    <div className="form-group">
                      <label className="form-label">Site URL</label>
                      <input
                        type="url"
                        className="form-input"
                        {...register('site_url')}
                      />
                    </div>

                    <div className="form-group">
                      <label className="form-label">Admin Email</label>
                      <input
                        type="email"
                        className="form-input"
                        {...register('admin_email')}
                      />
                    </div>

                    <div className="form-group">
                      <label className="flex items-center">
                        <input
                          type="checkbox"
                          className="form-checkbox mr-2"
                          {...register('maintenance_mode')}
                        />
                        <span className="text-sm">Maintenance Mode</span>
                      </label>
                      <div className="text-xs text-gray-500 mt-1">
                        Enable to show maintenance page to visitors
                      </div>
                    </div>
                  </div>
                )}

                {activeTab === 'content' && (
                  <div className="space-y-6">
                    <div className="form-group">
                      <label className="form-label">Posts Per Page</label>
                      <select className="form-input" {...register('posts_per_page')}>
                        <option value="10">10</option>
                        <option value="15">15</option>
                        <option value="20">20</option>
                        <option value="25">25</option>
                        <option value="30">30</option>
                      </select>
                    </div>

                    <div className="form-group">
                      <label className="flex items-center">
                        <input
                          type="checkbox"
                          className="form-checkbox mr-2"
                          {...register('allow_comments')}
                        />
                        <span className="text-sm">Allow Comments</span>
                      </label>
                    </div>

                    <div className="form-group">
                      <label className="flex items-center">
                        <input
                          type="checkbox"
                          className="form-checkbox mr-2"
                          {...register('moderation_required')}
                        />
                        <span className="text-sm">Require Comment Moderation</span>
                      </label>
                    </div>

                    <div className="bg-gray-50 p-4 rounded-lg">
                      <h4 className="font-medium text-gray-900 mb-2">Content Guidelines</h4>
                      <ul className="text-sm text-gray-600 space-y-1">
                        <li>• Images should be optimized for web (under 1MB)</li>
                        <li>• Use descriptive alt text for accessibility</li>
                        <li>• Articles should be at least 300 words for SEO</li>
                        <li>• Include relevant tags and categories</li>
                      </ul>
                    </div>
                  </div>
                )}

                {activeTab === 'seo' && (
                  <div className="space-y-6">
                    {/* Success/Error Message */}
                    {message && (
                      <div className={`p-4 rounded-lg ${message.includes('✅') ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>
                        {message}
                      </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="form-group">
                        <label className="form-label">Назва сайту *</label>
                        <input
                          type="text"
                          className="form-input"
                          placeholder="Science Digest News"
                          {...register('site_name', { required: 'Site name is required' })}
                        />
                        {errors.site_name && (
                          <div className="form-error">{errors.site_name.message}</div>
                        )}
                      </div>

                      <div className="form-group">
                        <label className="form-label">Canonical URL</label>
                        <input
                          type="url"
                          className="form-input"
                          placeholder="https://sciencedigestnews.com"
                          {...register('canonical_url')}
                        />
                      </div>
                    </div>

                    <div className="form-group">
                      <label className="form-label">Опис сайту *</label>
                      <textarea
                        className="form-input"
                        rows="3"
                        placeholder="Останні наукові відкриття та дослідження з усього світу..."
                        {...register('site_description', { required: 'Description is required' })}
                      />
                      {errors.site_description && (
                        <div className="form-error">{errors.site_description.message}</div>
                      )}
                    </div>

                    <div className="form-group">
                      <label className="form-label">Ключові слова</label>
                      <input
                        type="text"
                        className="form-input"
                        placeholder="наука, технології, медицина, дослідження"
                        {...register('site_keywords')}
                      />
                      <div className="text-xs text-gray-500 mt-1">
                        Розділяйте ключові слова комами
                      </div>
                    </div>

                    <div className="form-group">
                      <label className="form-label">Open Graph зображення</label>
                      <input
                        type="url"
                        className="form-input"
                        placeholder="https://images.unsplash.com/photo-..."
                        {...register('og_image')}
                      />
                      <div className="text-xs text-gray-500 mt-1">
                        Рекомендований розмір: 1200x630 пікселів
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="form-group">
                        <label className="form-label">Twitter Handle</label>
                        <input
                          type="text"
                          className="form-input"
                          placeholder="@sciencedigestnews"
                          {...register('twitter_handle')}
                        />
                      </div>

                      <div className="form-group">
                        <label className="form-label">Мова сайту</label>
                        <select className="form-input" {...register('language')}>
                          <option value="uk-UA">Українська (uk-UA)</option>
                          <option value="en-US">English (en-US)</option>
                          <option value="ru-RU">Русский (ru-RU)</option>
                        </select>
                      </div>
                    </div>

                    <div className="form-group">
                      <label className="form-label">Robots Meta Tag</label>
                      <select className="form-input" {...register('robots')}>
                        <option value="index, follow">Index, Follow (рекомендовано)</option>
                        <option value="index, nofollow">Index, No Follow</option>
                        <option value="noindex, follow">No Index, Follow</option>
                        <option value="noindex, nofollow">No Index, No Follow</option>
                      </select>
                    </div>

                    <div className="bg-blue-50 p-4 rounded-lg">
                      <h4 className="font-medium text-blue-900 mb-2">💡 Важливо для соціальних мереж</h4>
                      <ul className="text-sm text-blue-800 space-y-1">
                        <li>• Зміни в WhatsApp/Telegram відображаються через 5-10 хвилин</li>
                        <li>• Facebook/Instagram можуть кешувати до 24 годин</li>
                        <li>• Для негайного оновлення використовуйте Facebook Debugger</li>
                        <li>• Open Graph зображення повинно бути доступне публічно</li>
                      </ul>
                    </div>
                  </div>
                )}

                {activeTab === 'security' && (
                  <div className="space-y-6">
                    <div className="bg-red-50 p-4 rounded-lg">
                      <h4 className="font-medium text-red-900 mb-2">Security Status</h4>
                      <div className="space-y-2 text-sm">
                        <div className="flex items-center justify-between">
                          <span className="text-red-800">SSL Certificate</span>
                          <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs">Active</span>
                        </div>
                        <div className="flex items-center justify-between">
                          <span className="text-red-800">Two-Factor Authentication</span>
                          <span className="bg-yellow-100 text-yellow-800 px-2 py-1 rounded text-xs">Recommended</span>
                        </div>
                        <div className="flex items-center justify-between">
                          <span className="text-red-800">Password Policy</span>
                          <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs">Strong</span>
                        </div>
                      </div>
                    </div>

                    <div className="form-group">
                      <label className="form-label">Session Timeout (minutes)</label>
                      <select className="form-input">
                        <option value="30">30 minutes</option>
                        <option value="60">1 hour</option>
                        <option value="120">2 hours</option>
                        <option value="480">8 hours</option>
                      </select>
                    </div>

                    <div className="form-group">
                      <label className="form-label">Failed Login Attempts</label>
                      <select className="form-input">
                        <option value="3">3 attempts</option>
                        <option value="5">5 attempts</option>
                        <option value="10">10 attempts</option>
                      </select>
                    </div>
                  </div>
                )}

                {activeTab === 'integrations' && (
                  <div className="space-y-6">
                    {/* Google Search Console Section */}
                    <div className="bg-blue-50 p-4 rounded-lg">
                      <h4 className="font-medium text-blue-900 mb-3 flex items-center">
                        🔍 Google Search Console
                      </h4>
                      
                      <div className="space-y-4">
                        <div className="form-group">
                          <label className="form-label">Google Search Console Verification Code</label>
                          <input
                            type="text"
                            className="form-input"
                            placeholder="google1234567890abcdef.html"
                            {...register('gsc_verification_code')}
                          />
                          <div className="text-xs text-gray-600 mt-1">
                            HTML file verification code from Google Search Console
                          </div>
                        </div>

                        <div className="form-group">
                          <label className="form-label">Meta Tag Verification</label>
                          <input
                            type="text"
                            className="form-input"
                            placeholder="content=abcd1234567890..."
                            {...register('gsc_meta_verification')}
                          />
                          <div className="text-xs text-gray-600 mt-1">
                            Meta tag content value for verification
                          </div>
                        </div>

                        <div className="form-group">
                          <label className="form-label">Property URL</label>
                          <input
                            type="url"
                            className="form-input"
                            placeholder="https://sciencedigestnews.com"
                            {...register('gsc_property_url')}
                          />
                          <div className="text-xs text-gray-600 mt-1">
                            Your verified Search Console property URL
                          </div>
                        </div>

                        <div className="bg-white p-3 rounded border">
                          <h5 className="font-medium text-sm mb-2">Setup Instructions:</h5>
                          <ol className="text-xs text-gray-600 space-y-1 list-decimal list-inside">
                            <li>Go to <a href="https://search.google.com/search-console" target="_blank" className="text-blue-600 hover:underline">Google Search Console</a></li>
                            <li>Add your property (sciencedigestnews.com)</li>
                            <li>Choose HTML file or Meta tag verification method</li>
                            <li>Copy the verification code and paste it above</li>
                            <li>Save settings and verify in Search Console</li>
                          </ol>
                        </div>
                      </div>
                    </div>

                    {/* Analytics Section */}
                    <div className="form-group">
                      <label className="flex items-center">
                        <input
                          type="checkbox"
                          className="form-checkbox mr-2"
                          {...register('analytics_enabled')}
                        />
                        <span className="text-sm">Enable Analytics</span>
                      </label>
                    </div>

                    <div className="space-y-4">
                      <div>
                        <h4 className="font-medium text-gray-900 mb-3">Available Integrations</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="border rounded-lg p-4">
                            <div className="flex items-center justify-between mb-2">
                              <span className="font-medium">Google Analytics</span>
                              <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs">Connected</span>
                            </div>
                            <div className="text-sm text-gray-600">Track website visitors and behavior</div>
                          </div>
                          
                          <div className="border rounded-lg p-4">
                            <div className="flex items-center justify-between mb-2">
                              <span className="font-medium">Google Search Console</span>
                              <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs">Configured</span>
                            </div>
                            <div className="text-sm text-gray-600">Monitor search performance and SEO</div>
                          </div>
                          
                          <div className="border rounded-lg p-4">
                            <div className="flex items-center justify-between mb-2">
                              <span className="font-medium">Social Media</span>
                              <span className="bg-gray-100 text-gray-800 px-2 py-1 rounded text-xs">Available</span>
                            </div>
                            <div className="text-sm text-gray-600">Auto-post to social platforms</div>
                          </div>
                          
                          <div className="border rounded-lg p-4">
                            <div className="flex items-center justify-between mb-2">
                              <span className="font-medium">Email Newsletter</span>
                              <span className="bg-gray-100 text-gray-800 px-2 py-1 rounded text-xs">Available</span>
                            </div>
                            <div className="text-sm text-gray-600">Send newsletters to subscribers</div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Settings;